use std::{fs,path::Path};fn main(){let arg=std::env::args().nth(1).unwrap();let p=Path::new(&arg);let s=fs::read_to_string(p.join("CONTROL.tsv")).unwrap();let rows:Vec<_>=s.lines().skip(1).map(|l|l.split('\t').collect::<Vec<_>>()).collect();let n=rows.len();let yes=rows.iter().filter(|v|v[3]=="verified").count();let control=rows.iter().filter(|v|v[18].starts_with("Some(")).count();let mut x=String::from("<svg xmlns='http://www.w3.org/2000/svg' width='980' height='300'><rect width='980' height='300' fill='white'/><g font-family='Arial' fill='#183845'><text x='35' y='35' font-size='22'>One-pencil bounded gate: retained outcomes</text>");for(i,(label,k,col))in[("Joint source/target core",yes,"#287f82"),("Existing Compact control",control,"#bf773c")].iter().enumerate(){let y=85+i*75;let w=*k as f64/n as f64*540.;x+=&format!("<text x='35' y='{}' font-size='16'>{label}</text><rect x='270' y='{y}' width='{w}' height='34' fill='{col}'/><text x='{}' y='{}' font-size='17'>{k}/{n}</text>",y+23,280.+w,y+24);}x+="<text x='35' y='250' font-size='14'>Three candidate missing-input-row outcomes remain; no principal search is counted as successful there.</text><text x='35' y='279' font-size='13'>hec_anchor_collision_20261116 / one-pencil gate / exact six-input correctness counts, not speed.</text></g></svg>";fs::write(p.join("ONE-PENCIL.svg"),x).unwrap();}
